import{K as l,a as i,c,b as a,k as o,q as n,ac as s}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"Excel Power Query 导入、清洗、合并与刷新","description":"用获取和转换数据建立可重复的月报流程，指定类型与区域设置，追加多月数据、合并产品表、检查错误行并刷新结果。","frontmatter":{"title":"Excel Power Query 导入、清洗、合并与刷新","description":"用获取和转换数据建立可重复的月报流程，指定类型与区域设置，追加多月数据、合并产品表、检查错误行并刷新结果。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"用获取和转换数据建立可重复的月报流程，指定类型与区域设置，追加多月数据、合并产品表、检查错误行并刷新结果。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 数据透视表、切片器与透视图","link":"/tools/office/excel/pivots"},"next":{"text":"Excel 进阶分析：数据模型、目标求解与方案比较","link":"/tools/office/excel/analysis"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 数据透视表、切片器与透视图","link":"/tools/office/excel/pivots"},"next":{"text":"Excel 进阶分析：数据模型、目标求解与方案比较","link":"/tools/office/excel/analysis"}},"headers":[],"relativePath":"tools/office/excel/power-query.md","filePath":"tools/office/excel/power-query.md"}'),h={name:"tools/office/excel/power-query.md"},k=Object.assign(h,{setup(p){const t={path:"/tools/office/excel/power-query",app:"Excel",title:"把月报清洗步骤保存下来",steps:[{tab:"数据",command:"从表格/区域",setting:"来源：Sales；查询名：订单清洗",anchor:"walkthrough-1"},{tab:"查询编辑器的列标题",command:"筛选箭头",setting:"状态：已完成；日期：十月范围",anchor:"walkthrough-2",surface:"area",app:"Power Query"},{tab:"开始",command:"关闭并加载",setting:"加载到：新工作表；金额合计：3160",anchor:"walkthrough-3",app:"Power Query"}]};return(d,e)=>{const r=l("OfficeGuide");return i(),c("div",null,[e[0]||(e[0]=a("h1",{id:"excel-power-query-导入、清洗、合并与刷新",tabindex:"-1"},[o("Excel Power Query 导入、清洗、合并与刷新 "),a("a",{class:"header-anchor",href:"#excel-power-query-导入、清洗、合并与刷新","aria-label":'Permalink to "Excel Power Query 导入、清洗、合并与刷新"'},"​")],-1)),e[1]||(e[1]=a("p",null,[o("每月都要重复导入、删空行、改类型和合并表时，可以把步骤保存为 Power Query 查询。它主要负责数据准备，计算后的输出还可以交给透视表或图表。Windows、Mac、网页版的连接器和编辑/刷新能力依版本与许可不同，先检查实际环境。"),a("a",{href:"https://support.microsoft.com/en-us/excel/power-query-for-excel-help",target:"_blank",rel:"noopener noreferrer"},"微软 Power Query 帮助")],-1)),n(r,{guide:t}),e[2]||(e[2]=s('<h2 id="import" tabindex="-1">从现有表格开始 <a class="header-anchor" href="#import" aria-label="Permalink to &quot;从现有表格开始 {#import}&quot;">​</a></h2><ol><li>在<a href="/tools/office/excel/start#table">Sales 表格</a>中选择一个单元格。</li><li>点击“数据 → 从表格/区域”，打开查询编辑器。</li><li>把查询命名为 <code>订单清洗</code>，在右侧查看“应用的步骤”。</li><li>设置订单号为文本、日期为日期、数量为整数、单价和金额为合适的数值类型。</li><li>若日期来自不同地区格式，右击列选择使用区域设置更改类型，明确源格式所属区域。</li></ol><p>从文本/CSV 导入时先检查编码、分隔符和预览。编号列应尽早设为文本，避免自动类型识别先把前导零或长数字丢掉；必要时删除自动生成的类型步骤，重新指定类型。</p><h2 id="clean" tabindex="-1">清洗步骤与错误行 <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;清洗步骤与错误行 {#clean}&quot;">​</a></h2><p>对部门和产品文本使用修整/清理，过滤真正的空记录，保留必要字段。每做一步观察行数和示例值，确认没有无意排除有效记录。</p><p>数据错误应先“保留错误”查看原因，或建立专门的错误检查查询。直接删除错误行会让报表总额变小，却把原因藏起来。去重也必须明确键：同一订单号可能有多条产品明细，若业务粒度是一行一个产品，仅按订单号去重会丢掉正常记录。</p><h2 id="combine" tabindex="-1">追加与合并 <a class="header-anchor" href="#combine" aria-label="Permalink to &quot;追加与合并 {#combine}&quot;">​</a></h2><p>“追加”把结构相同的数据上下拼接，例如 10 月和 11 月订单；字段按列名对应，所以“部门”和“部门名称”会成为不同列，需要先统一名称。“合并”根据键把另一张表的列连接过来，例如按产品获取分类或标准价格。</p><p>先把产品表转成 Excel 表格并加载为查询，再在订单查询中选择“合并查询”，指定两边的产品字段。保留全部订单时可选择左外部连接，展开匹配列。合并前后比较行数：如果产品表同一个键出现两行，一条订单可能展开成两行，使金额被重复统计。</p><p>月度文件很多时可用“从文件夹”获取数据，再筛选需要的扩展名和命名规则后合并。排除临时锁文件、旧备份和输出文件；检查子目录是否被包含，避免把汇总结果再次读回形成重复。</p><h2 id="load" tabindex="-1">加载与刷新 <a class="header-anchor" href="#load" aria-label="Permalink to &quot;加载与刷新 {#load}&quot;">​</a></h2><p>通过“关闭并加载到”选择新工作表表格，或只创建连接/加载到数据模型。输出表是查询结果，手动改这里的值可能在下次刷新时被覆盖；需要修正数据，应改源数据或查询步骤。</p><p>修改一条源记录，然后“数据 → 全部刷新”，确认输出改变。若有后续透视表，等查询结束后再刷新并核对透视结果。不要在刷新尚未完成时导出月报。</p><p>共享给他人前检查文件路径、账号和数据源权限。能打开工作簿不代表能连接你的本机文件夹。跨来源合并时尊重隐私级别设置，不为了消除提示就把所有来源统一设成公开。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>以八条订单为源，在查询中只保留已完成且日期在 10 月的记录，加载到新表。应有 <strong>五行，金额合计 3160</strong>。把 O004 的数量从 5 改成 6，确认源金额为 480，刷新后结果应为 3240；恢复数量并重新刷新，回到 3160。</p><p>记录查询每步的目的和输入文件约定。第二次刷新无需重新手工删除或复制内容，且行数与金额可解释，才算建立了可重复流程。</p><h2 id="walkthrough" tabindex="-1">图示跟做：把月报清洗步骤保存下来 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：把月报清洗步骤保存下来 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：进入编辑器并检查类型 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：进入编辑器并检查类型 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：数据 → 从表格/区域。</strong></p><p>选中 Sales 中一个单元格，点击“数据 → 从表格/区域”。在查询编辑器中把订单号设文本，日期设日期，数量设整数，金额设数值。每次转换后看是否出现 Error；错误要先查看原因，不要直接删掉所有错误行让结果看起来整齐。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：按两项条件筛选 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：按两项条件筛选 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：查询编辑器的列标题 → 筛选箭头。</strong></p><p>点击状态列筛选箭头，只保留已完成；日期列使用筛选，起点为 2026-10-01，终点为 2026-11-01 之前。检查右侧应用的步骤是否留下筛选记录，预览应该有五行。状态筛选和日期筛选缺一项都无法得到本月已完成口径。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：从源数据变更验证可重复刷新 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：从源数据变更验证可重复刷新 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：开始 → 关闭并加载。</strong></p><p>关闭并加载到新工作表，检查行数五行、金额总计 3160。回到源表把 O004 数量改为 6，确认源金额更新，再在 Excel 的数据选项卡执行全部刷新，等待查询完成，应得到 3240。恢复数量并刷新，确认重新回到 3160。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>图示中的筛选列箭头位于查询编辑器表头，Excel 主窗口的数据筛选是另一套操作。不要在查询输出表直接改金额；刷新时这些手改可能被覆盖。</p>',30))])}}});export{f as __pageData,k as default};
